#include <iostream>
#include <string>
#include <string_view>

struct LanguageProfile {
    std::string_view name;
    std::string_view paradigm;
    int releaseYear;
};

void displayProfile(const LanguageProfile& lang) {
    std::cout << lang.name << " (" << lang.releaseYear << "): " 
              << lang.paradigm << "\n";
}

int main() {
    const LanguageProfile languages[] = {
        {"Perl", "Scripting / Text Processing", 1987},
        {"Python", "Multi-paradigm / Extensible", 1991},
        {"Java", "Object-Oriented / Virtual Machine", 1991},
        {"Scala", "Object-Oriented / Functional", 2003}
    };

    for (const auto& lang : languages) {
        displayProfile(lang);
    }
    return 0;
}

#include <iostream>
#include <string>

class BankAccount {
private:
    std::string accountHolder;
    double balance;

public:
    BankAccount(std::string name, double initialBalance) 
        : accountHolder(std::move(name)), balance(initialBalance > 0.0 ? initialBalance : 0.0) {}

    void deposit(double amount) {
        if (amount > 0.0) {
            balance += amount;
        }
    }

    void withdraw(double amount) {
        if (amount > 0.0 && amount <= balance) {
            balance -= amount;
        }
    }

    double getBalance() const {
        return balance;
    }

    const std::string& getHolder() const {
        return accountHolder;
    }
};

int main() {
    BankAccount account1{"Alice", 1000.0};
    BankAccount account2{"Bob", 500.0};

    account1.deposit(250.0);
    account2.withdraw(100.0);

    std::cout << account1.getHolder() << " balance: $" << account1.getBalance() << "\n";
    std::cout << account2.getHolder() << " balance: $" << account2.getBalance() << "\n";

    return 0;
}
